"""Rebuild css/desktop-standalone.css: tokens, embedded fonts, the result view and the window, in one file
that can replace the /*STYLE*/ block in src/heocr_desktop/ui/index.html.   python tools/make_standalone.py"""
from pathlib import Path

CSS = Path(__file__).resolve().parent.parent / "css"
parts = [(CSS / n).read_text(encoding="utf-8") for n in ("tokens.css", "fonts-embedded.css", "result.css", "desktop.css")]
(CSS / "desktop-standalone.css").write_text(
    "/* HeOCR desktop: one self-contained file = tokens.css + fonts-embedded.css + result.css + desktop.css.\n"
    "   Generated by tools/make_standalone.py; edit the four sources instead. */\n" + "\n".join(parts), encoding="utf-8")
print("wrote desktop-standalone.css")
